// swift-tools-version:5.9
import PackageDescription

let package = Package(
    name: "Shop",
    targets: [
        .target(name: "Shop"),
        .testTarget(name: "ShopTests", dependencies: ["Shop"]),
    ]
)

base.Sources/Shop/Cart.swift:
public struct Cart {
    public private(set) var items: [Int] = []

    public init() {}

    public mutating func add(_ price: Int) {
        items.append(price)
    }

    public var total: Int {
        items.reduce(0, +)
    }
}

base.Sources/Shop/Price.swift:
public func discounted(_ price: Int, percent: Int) -> Int {
    price - price * percent / 100
}

base.Tests/ShopTests/CartTests.swift:
import XCTest
@testable import Shop

final class CartTests: XCTestCase {
    func testEmptyCartTotalsZero() {
        let cart = Cart()
        XCTAssertEqual(cart.total, 0)
    }

    func testAddingItemsSumsThem() {
        var cart = Cart()
        cart.add(2)
        cart.add(3)
        XCTAssertEqual(cart.total, 5)
        XCTAssertEqual(cart.items.count, 2)
    }
}

base.Tests/ShopTests/DiscountTests.swift:
import Testing
@testable import Shop

@Suite("Discounts")
struct DiscountTests {
    @Test func tenPercentOff() {
        #expect(discounted(100, percent: 10) == 90)
    }

    @Test("No discount keeps the price")
    func noDiscount() {
        #expect(discounted(100, percent: 0) == 100)
    }
}

